// EnumerateStereoisomers' doctests and more; values from Python's module in
// RDKit 2026.03.6, generated by running it on the same input.

use rdkit_cxx::Result;
use rdkit_cxx::chem::enumerate_stereoisomers::*;
use rdkit_cxx::chem::{Mol, mol_from_smiles, mol_to_cx_smiles, mol_to_smiles};
use rdkit_cxx::rd_random::Random;

fn sorted(isomers: Stereoisomers) -> Vec<String> {
    let mut smis: Vec<String> = isomers
        .map(|m| mol_to_smiles(&m.unwrap()).unwrap())
        .collect();
    smis.sort();
    smis
}

fn ordered(isomers: impl Iterator<Item = Result<Mol>>) -> Vec<String> {
    isomers
        .map(|m| mol_to_smiles(&m.unwrap()).unwrap())
        .collect()
}

fn options() -> StereoEnumerationOptions {
    StereoEnumerationOptions::default()
}

#[test]
fn counts() -> Result<()> {
    assert_eq!(
        get_stereoisomer_count(&mol_from_smiles("BrC(Cl)(F)CCC(O)C")?)?,
        4
    );
    assert_eq!(get_stereoisomer_count(&mol_from_smiles("CC(Cl)(O)C")?)?, 1);
    assert_eq!(
        get_stereoisomer_count(&mol_from_smiles("BrC(Cl)(F)C=CC(O)C")?)?,
        8
    );
    assert_eq!(get_stereoisomer_count(&mol_from_smiles("CCO")?)?, 1);
    Ok(())
}

#[test]
fn enumerations() -> Result<()> {
    // all
    let isomers = enumerate_stereoisomers_with_options(
        &mol_from_smiles(r"BrC=CC1OC(C2)(F)C2(Cl)C1")?,
        &options(),
    )?;
    assert_eq!(
        sorted(isomers),
        [
            r"F[C@@]12C[C@@]1(Cl)C[C@@H](/C=C/Br)O2",
            r"F[C@@]12C[C@@]1(Cl)C[C@@H](/C=C\Br)O2",
            r"F[C@@]12C[C@@]1(Cl)C[C@H](/C=C/Br)O2",
            r"F[C@@]12C[C@@]1(Cl)C[C@H](/C=C\Br)O2",
            r"F[C@@]12C[C@]1(Cl)C[C@@H](/C=C/Br)O2",
            r"F[C@@]12C[C@]1(Cl)C[C@@H](/C=C\Br)O2",
            r"F[C@@]12C[C@]1(Cl)C[C@H](/C=C/Br)O2",
            r"F[C@@]12C[C@]1(Cl)C[C@H](/C=C\Br)O2",
            r"F[C@]12C[C@@]1(Cl)C[C@@H](/C=C/Br)O2",
            r"F[C@]12C[C@@]1(Cl)C[C@@H](/C=C\Br)O2",
            r"F[C@]12C[C@@]1(Cl)C[C@H](/C=C/Br)O2",
            r"F[C@]12C[C@@]1(Cl)C[C@H](/C=C\Br)O2",
            r"F[C@]12C[C@]1(Cl)C[C@@H](/C=C/Br)O2",
            r"F[C@]12C[C@]1(Cl)C[C@@H](/C=C\Br)O2",
            r"F[C@]12C[C@]1(Cl)C[C@H](/C=C/Br)O2",
            r"F[C@]12C[C@]1(Cl)C[C@H](/C=C\Br)O2"
        ]
    );
    // embedding
    let isomers = enumerate_stereoisomers_with_options(
        &mol_from_smiles(r"BrC=CC1OC(C2)(F)C2(Cl)C1")?,
        &StereoEnumerationOptions {
            try_embedding: true,
            ..options()
        },
    )?;
    assert_eq!(
        sorted(isomers),
        [
            r"F[C@@]12C[C@]1(Cl)C[C@@H](/C=C/Br)O2",
            r"F[C@@]12C[C@]1(Cl)C[C@@H](/C=C\Br)O2",
            r"F[C@@]12C[C@]1(Cl)C[C@H](/C=C/Br)O2",
            r"F[C@@]12C[C@]1(Cl)C[C@H](/C=C\Br)O2",
            r"F[C@]12C[C@@]1(Cl)C[C@@H](/C=C/Br)O2",
            r"F[C@]12C[C@@]1(Cl)C[C@@H](/C=C\Br)O2",
            r"F[C@]12C[C@@]1(Cl)C[C@H](/C=C/Br)O2",
            r"F[C@]12C[C@@]1(Cl)C[C@H](/C=C\Br)O2"
        ]
    );
    // unique
    let isomers =
        enumerate_stereoisomers_with_options(&mol_from_smiles(r"FC(Cl)C=CC=CC(F)Cl")?, &options())?;
    assert_eq!(
        sorted(isomers),
        [
            r"F[C@@H](Cl)/C=C/C=C/[C@@H](F)Cl",
            r"F[C@@H](Cl)/C=C\C=C/[C@@H](F)Cl",
            r"F[C@@H](Cl)/C=C\C=C\[C@@H](F)Cl",
            r"F[C@H](Cl)/C=C/C=C/[C@@H](F)Cl",
            r"F[C@H](Cl)/C=C/C=C/[C@H](F)Cl",
            r"F[C@H](Cl)/C=C/C=C\[C@@H](F)Cl",
            r"F[C@H](Cl)/C=C\C=C/[C@@H](F)Cl",
            r"F[C@H](Cl)/C=C\C=C/[C@H](F)Cl",
            r"F[C@H](Cl)/C=C\C=C\[C@@H](F)Cl",
            r"F[C@H](Cl)/C=C\C=C\[C@H](F)Cl"
        ]
    );
    // not_unique
    let isomers = enumerate_stereoisomers_with_options(
        &mol_from_smiles(r"FC(Cl)C=CC=CC(F)Cl")?,
        &StereoEnumerationOptions {
            unique: false,
            ..options()
        },
    )?;
    assert_eq!(
        sorted(isomers),
        [
            r"F[C@@H](Cl)/C=C/C=C/[C@@H](F)Cl",
            r"F[C@@H](Cl)/C=C\C=C/[C@@H](F)Cl",
            r"F[C@@H](Cl)/C=C\C=C\[C@@H](F)Cl",
            r"F[C@@H](Cl)/C=C\C=C\[C@@H](F)Cl",
            r"F[C@H](Cl)/C=C/C=C/[C@@H](F)Cl",
            r"F[C@H](Cl)/C=C/C=C/[C@@H](F)Cl",
            r"F[C@H](Cl)/C=C/C=C/[C@H](F)Cl",
            r"F[C@H](Cl)/C=C/C=C\[C@@H](F)Cl",
            r"F[C@H](Cl)/C=C/C=C\[C@@H](F)Cl",
            r"F[C@H](Cl)/C=C\C=C/[C@@H](F)Cl",
            r"F[C@H](Cl)/C=C\C=C/[C@@H](F)Cl",
            r"F[C@H](Cl)/C=C\C=C/[C@H](F)Cl",
            r"F[C@H](Cl)/C=C\C=C\[C@@H](F)Cl",
            r"F[C@H](Cl)/C=C\C=C\[C@@H](F)Cl",
            r"F[C@H](Cl)/C=C\C=C\[C@H](F)Cl",
            r"F[C@H](Cl)/C=C\C=C\[C@H](F)Cl"
        ]
    );
    // unassigned
    let isomers = enumerate_stereoisomers_with_options(
        &mol_from_smiles(r"BrC=C[C@H]1OC(C2)(F)C2(Cl)C1")?,
        &options(),
    )?;
    assert_eq!(
        sorted(isomers),
        [
            r"F[C@@]12C[C@@]1(Cl)C[C@@H](/C=C/Br)O2",
            r"F[C@@]12C[C@@]1(Cl)C[C@@H](/C=C\Br)O2",
            r"F[C@@]12C[C@]1(Cl)C[C@@H](/C=C/Br)O2",
            r"F[C@@]12C[C@]1(Cl)C[C@@H](/C=C\Br)O2",
            r"F[C@]12C[C@@]1(Cl)C[C@@H](/C=C/Br)O2",
            r"F[C@]12C[C@@]1(Cl)C[C@@H](/C=C\Br)O2",
            r"F[C@]12C[C@]1(Cl)C[C@@H](/C=C/Br)O2",
            r"F[C@]12C[C@]1(Cl)C[C@@H](/C=C\Br)O2"
        ]
    );
    // assigned
    let isomers = enumerate_stereoisomers_with_options(
        &mol_from_smiles(r"BrC=C[C@H]1OC(C2)(F)C2(Cl)C1")?,
        &StereoEnumerationOptions {
            only_unassigned: false,
            ..options()
        },
    )?;
    assert_eq!(
        sorted(isomers),
        [
            r"F[C@@]12C[C@@]1(Cl)C[C@@H](/C=C/Br)O2",
            r"F[C@@]12C[C@@]1(Cl)C[C@@H](/C=C\Br)O2",
            r"F[C@@]12C[C@@]1(Cl)C[C@H](/C=C/Br)O2",
            r"F[C@@]12C[C@@]1(Cl)C[C@H](/C=C\Br)O2",
            r"F[C@@]12C[C@]1(Cl)C[C@@H](/C=C/Br)O2",
            r"F[C@@]12C[C@]1(Cl)C[C@@H](/C=C\Br)O2",
            r"F[C@@]12C[C@]1(Cl)C[C@H](/C=C/Br)O2",
            r"F[C@@]12C[C@]1(Cl)C[C@H](/C=C\Br)O2",
            r"F[C@]12C[C@@]1(Cl)C[C@@H](/C=C/Br)O2",
            r"F[C@]12C[C@@]1(Cl)C[C@@H](/C=C\Br)O2",
            r"F[C@]12C[C@@]1(Cl)C[C@H](/C=C/Br)O2",
            r"F[C@]12C[C@@]1(Cl)C[C@H](/C=C\Br)O2",
            r"F[C@]12C[C@]1(Cl)C[C@@H](/C=C/Br)O2",
            r"F[C@]12C[C@]1(Cl)C[C@@H](/C=C\Br)O2",
            r"F[C@]12C[C@]1(Cl)C[C@H](/C=C/Br)O2",
            r"F[C@]12C[C@]1(Cl)C[C@H](/C=C\Br)O2"
        ]
    );
    // or_group
    let isomers = enumerate_stereoisomers_with_options(
        &mol_from_smiles(r"C[C@H](F)[C@H](Cl)Br |o1:1,3|")?,
        &options(),
    )?;
    assert_eq!(
        sorted(isomers),
        [r"C[C@@H](F)[C@@H](Cl)Br", r"C[C@H](F)[C@H](Cl)Br"]
    );
    // and_group_only
    let isomers = enumerate_stereoisomers_with_options(
        &mol_from_smiles(r"C[C@H](F)[C@H](Cl)CC(Br)I |&1:1,3|")?,
        &StereoEnumerationOptions {
            only_stereo_groups: true,
            ..options()
        },
    )?;
    assert_eq!(
        sorted(isomers),
        [r"C[C@@H](F)[C@@H](Cl)CC(Br)I", r"C[C@H](F)[C@H](Cl)CC(Br)I"]
    );
    // nothing
    let isomers = enumerate_stereoisomers_with_options(&mol_from_smiles(r"CCO")?, &options())?;
    assert_eq!(sorted(isomers), [r"CCO"]);
    // ring
    let isomers =
        enumerate_stereoisomers_with_options(&mol_from_smiles(r"C1CC(C)CC(C)C1")?, &options())?;
    assert_eq!(
        sorted(isomers),
        [
            r"C[C@@H]1CCC[C@@H](C)C1",
            r"C[C@@H]1CCC[C@H](C)C1",
            r"C[C@H]1CCC[C@H](C)C1"
        ]
    );
    Ok(())
}

#[test]
fn large_enumerations() -> Result<()> {
    let m = mol_from_smiles(&format!("Br{}F", "[CH](Cl)".repeat(20)))?;
    let all = StereoEnumerationOptions {
        max_isomers: 0,
        ..options()
    };
    assert_eq!(
        ordered(enumerate_stereoisomers_with_options(&m, &all)?.take(5)),
        [
            r"F[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)Br",
            r"F[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@H](Cl)Br",
            r"F[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@H](Cl)[C@@H](Cl)Br",
            r"F[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@H](Cl)[C@H](Cl)Br",
            r"F[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@H](Cl)[C@@H](Cl)[C@@H](Cl)Br"
        ]
    );
    // Sampled with a seed, as with rand=0xf00d.
    let seeded = StereoEnumerationOptions {
        max_isomers: 3,
        rand: Some(Random::new(0xf00d)),
        ..options()
    };
    assert_eq!(
        ordered(enumerate_stereoisomers_with_options(&m, &seeded)?),
        [
            r"F[C@@H](Cl)[C@H](Cl)[C@H](Cl)[C@H](Cl)[C@@H](Cl)[C@H](Cl)[C@H](Cl)[C@@H](Cl)[C@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@H](Cl)[C@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@H](Cl)[C@H](Cl)[C@H](Cl)[C@@H](Cl)Br",
            r"F[C@H](Cl)[C@H](Cl)[C@H](Cl)[C@@H](Cl)[C@H](Cl)[C@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@H](Cl)[C@@H](Cl)[C@H](Cl)[C@H](Cl)[C@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@H](Cl)[C@H](Cl)[C@@H](Cl)[C@@H](Cl)Br",
            r"F[C@@H](Cl)[C@@H](Cl)[C@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@H](Cl)[C@@H](Cl)Br"
        ]
    );
    // Sampled with the seed Python hashes from the molecule.
    let two = StereoEnumerationOptions {
        max_isomers: 2,
        ..options()
    };
    assert_eq!(
        ordered(enumerate_stereoisomers_with_options(&m, &two)?),
        [
            r"F[C@@H](Cl)[C@H](Cl)[C@H](Cl)[C@H](Cl)[C@H](Cl)[C@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@H](Cl)[C@@H](Cl)[C@@H](Cl)Br",
            r"F[C@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@H](Cl)[C@@H](Cl)[C@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@H](Cl)[C@@H](Cl)[C@@H](Cl)[C@H](Cl)[C@@H](Cl)[C@H](Cl)[C@H](Cl)Br"
        ]
    );
    let m = mol_from_smiles("CC(F)C(F)C(F)C(F)C(Cl)C(Br)C(I)C(O)C(N)C(S)C(P)CC")?;
    assert_eq!(get_stereoisomer_count(&m)?, 2048);
    assert_eq!(
        ordered(enumerate_stereoisomers(&m)?.take(3)),
        [
            r"CC[C@@H](P)[C@H](S)[C@H](N)[C@H](O)[C@@H](I)[C@H](Br)[C@@H](Cl)[C@@H](F)[C@H](F)[C@@H](F)[C@H](C)F",
            r"CC[C@@H](P)[C@H](S)[C@@H](N)[C@@H](O)[C@H](I)[C@H](Br)[C@H](Cl)[C@@H](F)[C@@H](F)[C@@H](F)[C@H](C)F",
            r"CC[C@H](P)[C@@H](S)[C@@H](N)[C@@H](O)[C@H](I)[C@@H](Br)[C@H](Cl)[C@@H](F)[C@H](F)[C@@H](F)[C@H](C)F"
        ]
    );
    assert_eq!(enumerate_stereoisomers(&m)?.count(), 1024);
    Ok(())
}

#[test]
fn embedded_isomers() -> Result<()> {
    let opts = StereoEnumerationOptions {
        try_embedding: true,
        ..options()
    };
    let isomers: Vec<Mol> =
        enumerate_stereoisomers_with_options(&mol_from_smiles("CC(F)Cl")?, &opts)?
            .collect::<Result<_>>()?;
    assert_eq!(isomers.len(), 2);
    for m in &isomers {
        assert_eq!(m.get_num_conformers(), 1);
        assert_eq!(m.get_prop("_MolFileChiralFlag")?, "1");
    }
    let cx: Vec<String> =
        enumerate_stereoisomers(&mol_from_smiles("C[C@H](F)[C@H](Cl)Br |o1:1,3|")?)?
            .map(|m| mol_to_cx_smiles(&m.unwrap()).unwrap())
            .collect();
    assert_eq!(cx, [r"C[C@@H](F)[C@@H](Cl)Br", r"C[C@H](F)[C@H](Cl)Br"]);
    Ok(())
}
